import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const A=JSON.parse('{"title":"WAF — enumerated source for the Data Services technology review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-data-services-checklist.md","filePath":"frameworks/waf-data-services-checklist.md"}'),o={name:"frameworks/waf-data-services-checklist.md"};function i(n,t,s,c,l,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="waf-—-enumerated-source-for-the-data-services-technology-review" tabindex="-1">WAF — enumerated source for the Data Services technology review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-data-services-technology-review" aria-label="Permalink to &quot;WAF — enumerated source for the Data Services technology review&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>waf.dataservices.yaml</code> scores the Data Services review. This page enumerates the Well-Architected service guides for Azure SQL Database, SQL Managed Instance, Cosmos DB, Database for PostgreSQL, Database for MySQL, Azure Managed Redis, Azure HorizonDB and Blob Storage, item by item. The rule file is written against this page only; every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/azure-architecture-review-data/" target="_blank" rel="noreferrer">Data Services — Well-Architected Review</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework service guides for the Databases category plus Azure Blob Storage, current at extraction (Azure Managed Redis added October 2026)</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The service-guide catalog was fetched on 2026-11-25. The Azure SQL Database and Azure Cosmos DB guides were fetched in full; the PostgreSQL, SQL Managed Instance, Azure Managed Redis, Azure HorizonDB, MySQL and Blob Storage guides were read through the Microsoft Learn MCP search excerpts of their configuration-recommendation tables. Rows not returned by those excerpts are summarised, mainly the SQL Managed Instance reliability, cost and performance sections, the MySQL reliability section beyond its first row, the Blob Storage cost, operations and performance sections, and the Azure Managed Redis tradeoffs. Re-read the full pages at the next recheck.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The review&#39;s questions are not published. The items below are <strong>Scout&#39;s</strong> reading of the guides and the <code>WAF-DATA-*</code> ids are Scout&#39;s. The Cosmos DB guide covers the NoSQL API only; the MySQL guide covers flexible server (single server is retired).</p><p>Sources (the code after each item names the page and section; -C is a workload design checklist bullet, -R a configuration recommendations row):</p><ul><li>[AMR] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-managed-redis" target="_blank" rel="noreferrer">Architecture best practices for Azure Managed Redis</a></li><li>[BLOB] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-blob-storage" target="_blank" rel="noreferrer">Architecture best practices for Azure Blob Storage</a> and <a href="https://learn.microsoft.com/azure/storage/blobs/security-recommendations" target="_blank" rel="noreferrer">Security recommendations for Blob storage</a> (code S)</li><li>[COS] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/cosmos-db" target="_blank" rel="noreferrer">Architecture best practices for Azure Cosmos DB for NoSQL</a></li><li>[HZ] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-horizondb" target="_blank" rel="noreferrer">Architecture best practices for Azure HorizonDB</a></li><li>[MI] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-sql-managed-instance/reliability" target="_blank" rel="noreferrer">Architecture best practices for Azure SQL Managed Instance</a> (security section read; other pillars summarised)</li><li>[MYS] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-database-for-mysql" target="_blank" rel="noreferrer">Architecture best practices for Azure Database for MySQL</a> and its <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-db-mysql-cost-optimization" target="_blank" rel="noreferrer">cost optimization</a> page</li><li>[PG] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/postgresql" target="_blank" rel="noreferrer">Architecture best practices for Azure Database for PostgreSQL</a></li><li>[SQL] <a href="https://learn.microsoft.com/azure/well-architected/service-guides/azure-sql-database" target="_blank" rel="noreferrer">Architecture best practices for Azure SQL Database</a></li><li>[GPV1] <a href="https://learn.microsoft.com/azure/storage/common/storage-account-upgrade" target="_blank" rel="noreferrer">Upgrade to a general-purpose v2 storage account</a> and the general-purpose v1 and legacy blob storage retirement pages (used for WAF-DATA-BLOB-16 only; the Blob Storage Well-Architected guide does not carry it)</li></ul><p>Collected datasets map as follows: <code>domains.databases.sqlServers</code>, <code>sqlDatabases</code>, <code>sqlManagedInstances</code>, <code>cosmosDbAccounts</code>, <code>postgreSqlFlexibleServers</code>, <code>mySqlFlexibleServers</code>, <code>redisCaches</code> (Azure Managed Redis is <code>microsoft.cache/redisenterprise</code>; the classic cache shares the dataset) and <code>domains.storage.storageAccounts</code>. Azure HorizonDB is not collected, so its items are manual.</p><p>The datasets now carry the settings the first pass lacked: SQL server <code>id</code>, <code>minimalTlsVersion</code> and <code>entraOnlyAuth</code>; database and managed-instance backup redundancy; managed-instance zone redundancy and customer-managed-key flag; Cosmos region and zone-redundant-region counts, automatic failover, backup type, network filter and key flag; PostgreSQL and MySQL high-availability mode, geo-redundant backup and (PostgreSQL) authentication; Redis TLS, non-TLS port, access-key setting and high availability; and storage shared-key access, key source and public network access. An absent string is <code>&#39;&#39;</code> and an absent boolean is <code>null</code> in the collection, and Newtonsoft JSONPath never matches a missing property with <code>==</code> or <code>!=</code> but does match a <code>null</code> or <code>&#39;&#39;</code> value with <code>!=</code>. Rules where absence is itself the finding are therefore written as &quot;is not the good value&quot; (storage minimum TLS, shared-key access, the SQL Entra-only flag). Two limits to know: the Cosmos zone item is satisfied by one zone-redundant region (a filter cannot compare two fields), and the Redis access-key setting is only projected for classic caches, so that rule is scoped to them.</p><p>Items that mix an automated check with something ARM does not carry (active geo-replication links, the immutable audit target and Always Encrypted, the user-assigned identity, vault soft delete, role assignments, failover tests) have been narrowed to the part that can be scored, and the doc row says what is left for a human.</p><h2 id="the-enumeration-—-104-items" tabindex="-1">The enumeration — 104 items <a class="header-anchor" href="#the-enumeration-—-104-items" aria-label="Permalink to &quot;The enumeration — 104 items&quot;">​</a></h2><h3 id="azure-sql-database-waf-data-sql-—-19-items" tabindex="-1">Azure SQL Database (WAF-DATA-SQL) — 19 items <a class="header-anchor" href="#azure-sql-database-waf-data-sql-—-19-items" aria-label="Permalink to &quot;Azure SQL Database (WAF-DATA-SQL) — 19 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-SQL-01</td><td>Reliability</td><td>SQL databases are zone redundant</td><td>✅ database zoneRedundant (master excluded)</td><td>SQL-RE-R</td></tr><tr><td>WAF-DATA-SQL-02</td><td>Reliability</td><td>Active geo-replication or failover groups protect against a regional failure</td><td>✅ <code>sqlFailoverGroups</code> <code>failoverGroupCount</code> (a server with no failover group is a finding; active geo-replication links are not collected, so a server protected by links alone is an exception to record); gated on <code>sqlFailoverGroupsMeasured</code></td><td>SQL-RE-C, SQL-RE-R</td></tr><tr><td>WAF-DATA-SQL-03</td><td>Reliability</td><td>Backups cover point-in-time restore, geo-restore and long-term retention, with immutability</td><td>❌ Manual — backup policy is a child resource, not collected</td><td>SQL-RE-R</td></tr><tr><td>WAF-DATA-SQL-04</td><td>Reliability</td><td>Critical databases use the Business Critical or Hyperscale tier</td><td>❌ Manual — the tier of each database is attached; which are critical is judgement</td><td>SQL-RE-C</td></tr><tr><td>WAF-DATA-SQL-05</td><td>Reliability</td><td>Applications retry with backoff and isolate connection pools by function</td><td>❌ Manual — client code, not ARM</td><td>SQL-RE-C, SQL-RE-R</td></tr><tr><td>WAF-DATA-SQL-06</td><td>Security</td><td>SQL servers have public network access disabled</td><td>✅ server publicNetworkAccess</td><td>SQL-SE-R</td></tr><tr><td>WAF-DATA-SQL-07</td><td>Security</td><td>Each SQL server has a private endpoint</td><td>✅ server to private endpoint join</td><td>SQL-SE-R</td></tr><tr><td>WAF-DATA-SQL-08</td><td>Security</td><td>The minimum TLS version is 1.2 or higher</td><td>✅ minimalTlsVersion; only 1.2 and 1.3 pass, so an empty value (which allows every version), None, 1.0 and 1.1 are findings</td><td>SQL-SE-R</td></tr><tr><td>WAF-DATA-SQL-09</td><td>Security</td><td>SQL authentication is disabled and Microsoft Entra-only authentication is on</td><td>✅ Entra-only flag; an absent flag (no Entra administrator) is a finding</td><td>SQL-SE-R</td></tr><tr><td>WAF-DATA-SQL-10</td><td>Security</td><td>Microsoft Defender for SQL is on Standard</td><td>✅ subscription Defender for SQL tier</td><td>SQL-SE-R</td></tr><tr><td>WAF-DATA-SQL-11</td><td>Security</td><td>Auditing is on with immutable storage, and sensitive data is protected with Always Encrypted or ledger</td><td>✅ <code>sqlServerAuditing</code> <code>auditingState</code> (only Enabled passes); the immutable audit target and column encryption are not collected; gated on <code>sqlServerAuditingMeasured</code></td><td>SQL-SE-R</td></tr><tr><td>WAF-DATA-SQL-12</td><td>Cost optimization</td><td>The service tier, serverless and elastic pools match each database&#39;s use</td><td>❌ Manual — elastic pools attached; databases are in the reliability item</td><td>SQL-CO-R</td></tr><tr><td>WAF-DATA-SQL-13</td><td>Cost optimization</td><td>Reserved capacity and Azure Hybrid Benefit are used for steady workloads</td><td>❌ Manual — reservations attached</td><td>SQL-CO-R</td></tr><tr><td>WAF-DATA-SQL-14</td><td>Cost optimization</td><td>Backup storage consumption is tuned and queries are optimised to cut resource use</td><td>❌ Manual — metrics, not ARM</td><td>SQL-CO-R</td></tr><tr><td>WAF-DATA-SQL-15</td><td>Operational excellence</td><td>SQL databases send diagnostics to Log Analytics</td><td>✅ diagnostic-settings coverage for the database type</td><td>SQL-OE-R</td></tr><tr><td>WAF-DATA-SQL-16</td><td>Operational excellence</td><td>SQL projects deploy through CI/CD and servers are backed up with Azure Backup</td><td>❌ Manual — practice, not ARM</td><td>SQL-OE-R</td></tr><tr><td>WAF-DATA-SQL-17</td><td>Performance efficiency</td><td>Query Store, automatic tuning and performance recommendations are enabled and acted on</td><td>❌ Manual — database-scoped configuration, not collected</td><td>SQL-PE-R</td></tr><tr><td>WAF-DATA-SQL-18</td><td>Performance efficiency</td><td>The vCore model, read scale-out and connection pooling are used</td><td>❌ Manual — databases attached with tier and replica count; connection pooling is client code</td><td>SQL-PE-C, SQL-PE-R</td></tr><tr><td>WAF-DATA-SQL-19</td><td>Reliability</td><td>Database backup storage is geo-redundant or geo-zone-redundant</td><td>✅ backup storage redundancy (master excluded); local, zone-only and empty values are findings</td><td>SQL-RE-C</td></tr></tbody></table><h3 id="azure-sql-managed-instance-waf-data-mi-—-11-items" tabindex="-1">Azure SQL Managed Instance (WAF-DATA-MI) — 11 items <a class="header-anchor" href="#azure-sql-managed-instance-waf-data-mi-—-11-items" aria-label="Permalink to &quot;Azure SQL Managed Instance (WAF-DATA-MI) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-MI-01</td><td>Reliability</td><td>Managed instances are zone redundant</td><td>✅ zoneRedundant; failover groups are child resources, not collected, so that half of the guide item is not scored</td><td>MI-RE</td></tr><tr><td>WAF-DATA-MI-02</td><td>Reliability</td><td>Backup storage is geo-redundant or geo-zone-redundant</td><td>✅ backup storage redundancy; local, zone-only and empty values are findings. Retention against the recovery point objective is not collected</td><td>MI-RE</td></tr><tr><td>WAF-DATA-MI-03</td><td>Security</td><td>The public data endpoint is off</td><td>✅ publicDataEndpointEnabled</td><td>MI-SE</td></tr><tr><td>WAF-DATA-MI-04</td><td>Security</td><td>Cross-network access uses private endpoints</td><td>❌ Manual — private endpoints attached</td><td>MI-SE</td></tr><tr><td>WAF-DATA-MI-05</td><td>Security</td><td>Microsoft Entra-only authentication is used</td><td>✅ Entra-only flag; an absent flag is a finding. The user-assigned identity half is not collected</td><td>MI-SE</td></tr><tr><td>WAF-DATA-MI-06</td><td>Security</td><td>TDE uses a customer-managed key</td><td>❌ Manual — customer-managed keys are requirement-driven; the instances not on a customer-managed key (cmkEnabled is not true) are attached as evidence, and the vault&#39;s soft delete and purge protection are not read</td><td>MI-SE</td></tr><tr><td>WAF-DATA-MI-07</td><td>Security</td><td>Defender for SQL is on, SQL Agent is off if unused, and the subnet NSG denies by default</td><td>❌ Manual — agent, NSG and subnet detail are not collected per instance</td><td>MI-SE</td></tr><tr><td>WAF-DATA-MI-08</td><td>Security</td><td>Server and operator auditing go to blob storage and Azure Monitor logs</td><td>✅ diagnostic-settings coverage for the managed-instance type (a setting present, not which categories or targets)</td><td>MI-SE</td></tr><tr><td>WAF-DATA-MI-09</td><td>Cost optimization</td><td>vCores and service tier are right-sized, with reservations and Azure Hybrid Benefit</td><td>❌ Manual — instances attached with sku and vCores</td><td>MI-CO</td></tr><tr><td>WAF-DATA-MI-10</td><td>Operational excellence</td><td>Maintenance windows and the update policy are chosen deliberately</td><td>❌ Manual — maintenance configurations attached (estate-wide)</td><td>MI-OE</td></tr><tr><td>WAF-DATA-MI-11</td><td>Performance efficiency</td><td>The service tier, vCores and storage are validated against the workload</td><td>❌ Manual — instances attached</td><td>MI-PE</td></tr></tbody></table><h3 id="azure-cosmos-db-waf-data-cos-—-17-items" tabindex="-1">Azure Cosmos DB (WAF-DATA-COS) — 17 items <a class="header-anchor" href="#azure-cosmos-db-waf-data-cos-—-17-items" aria-label="Permalink to &quot;Azure Cosmos DB (WAF-DATA-COS) — 17 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-COS-01</td><td>Reliability</td><td>Cosmos DB accounts are distributed across availability zones</td><td>✅ count of zone-redundant regions; an account with none is a finding (partial coverage is not detectable)</td><td>COS-RE-R</td></tr><tr><td>WAF-DATA-COS-02</td><td>Reliability</td><td>Accounts span at least two regions</td><td>✅ region count</td><td>COS-RE-R</td></tr><tr><td>WAF-DATA-COS-03</td><td>Reliability</td><td>Service-managed failover is enabled</td><td>✅ enableAutomaticFailover on multi-region, single-write accounts</td><td>COS-RE-R</td></tr><tr><td>WAF-DATA-COS-04</td><td>Reliability</td><td>Continuous backup with point-in-time restore is configured</td><td>✅ backup policy type is Continuous</td><td>COS-RE-C</td></tr><tr><td>WAF-DATA-COS-05</td><td>Security</td><td>Cosmos DB accounts have public network access disabled</td><td>✅ account publicNetworkAccess</td><td>COS-SE-R</td></tr><tr><td>WAF-DATA-COS-06</td><td>Security</td><td>Each Cosmos DB account has a private endpoint</td><td>✅ account to private endpoint join</td><td>COS-SE-R</td></tr><tr><td>WAF-DATA-COS-07</td><td>Security</td><td>Key-based (local) authentication is disabled in favour of Microsoft Entra ID</td><td>✅ disableLocalAuth</td><td>COS-SE-R</td></tr><tr><td>WAF-DATA-COS-08</td><td>Security</td><td>Accounts that accept public traffic limit it with virtual network rules or IP firewall rules</td><td>✅ public access on with no virtual network filter and no IP rules. Role-based access is not read</td><td>COS-SE-R</td></tr><tr><td>WAF-DATA-COS-09</td><td>Security</td><td>Microsoft Defender for Azure Cosmos DB is enabled</td><td>❌ Manual — Defender plan row attached; the plan name was not re-verified</td><td>COS-SE-R</td></tr><tr><td>WAF-DATA-COS-10</td><td>Security</td><td>Cosmos DB accounts send control-plane logs and metrics to Log Analytics</td><td>✅ diagnostic-settings coverage for the account type</td><td>COS-SE-C, COS-SE-R</td></tr><tr><td>WAF-DATA-COS-11</td><td>Security</td><td>Data is encrypted with customer-managed keys where regulation requires</td><td>❌ Manual — customer-managed keys are requirement-driven; the accounts not on a customer-managed key are attached as evidence</td><td>COS-SE-C</td></tr><tr><td>WAF-DATA-COS-12</td><td>Cost optimization</td><td>The throughput model, indexing policy, TTL and consistency level are chosen for cost</td><td>❌ Manual — container and database settings are data plane</td><td>COS-CO-R</td></tr><tr><td>WAF-DATA-COS-13</td><td>Cost optimization</td><td>Normalised RU consumption is monitored and alerted</td><td>❌ Manual — metric alert rules attached (estate-wide)</td><td>COS-CO-R</td></tr><tr><td>WAF-DATA-COS-14</td><td>Operational excellence</td><td>Accounts and containers deploy as code and SDKs are current</td><td>❌ Manual — practice, not ARM</td><td>COS-OE-R</td></tr><tr><td>WAF-DATA-COS-15</td><td>Operational excellence</td><td>Throttling, host resources and key metrics have alerts</td><td>❌ Manual — metric alert rules attached (estate-wide)</td><td>COS-OE-R</td></tr><tr><td>WAF-DATA-COS-16</td><td>Performance efficiency</td><td>Data model, partition key and queries are designed for performance</td><td>❌ Manual — data-plane design</td><td>COS-PE-R</td></tr><tr><td>WAF-DATA-COS-17</td><td>Performance efficiency</td><td>Regions are close to users and multi-region writes are used where clients are distributed</td><td>❌ Manual — accounts attached with location, region count and multi-region writes; where the users are is not collected</td><td>COS-PE-R</td></tr></tbody></table><h3 id="azure-database-for-postgresql-waf-data-pg-—-10-items" tabindex="-1">Azure Database for PostgreSQL (WAF-DATA-PG) — 10 items <a class="header-anchor" href="#azure-database-for-postgresql-waf-data-pg-—-10-items" aria-label="Permalink to &quot;Azure Database for PostgreSQL (WAF-DATA-PG) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-PG-01</td><td>Reliability</td><td>PostgreSQL servers use zone-redundant high availability</td><td>✅ highAvailability.mode is ZoneRedundant</td><td>PG-RE-R</td></tr><tr><td>WAF-DATA-PG-02</td><td>Reliability</td><td>Geo-redundant backup protects against regional failure</td><td>✅ geo-redundant backup is Enabled; a cross-region replica (the alternative) is not collected</td><td>PG-RE-R</td></tr><tr><td>WAF-DATA-PG-03</td><td>Security</td><td>PostgreSQL servers have public network access disabled</td><td>✅ network.publicNetworkAccess</td><td>PG-SE-R</td></tr><tr><td>WAF-DATA-PG-04</td><td>Security</td><td>Microsoft Entra authentication is enabled</td><td>✅ authConfig.activeDirectoryAuth; password authentication is collected for the follow-up. Managed identities are not collected</td><td>PG-SE-R</td></tr><tr><td>WAF-DATA-PG-05</td><td>Security</td><td>Private Link endpoints and network security groups or firewall rules segment access</td><td>❌ Manual — private endpoints attached; pairing is not computed because private-access servers need none</td><td>PG-SE-R</td></tr><tr><td>WAF-DATA-PG-06</td><td>Security</td><td>Defender for Cloud, row-level security, customer-managed keys, confidential compute and connection throttling are used where needed</td><td>❌ Manual — servers attached with data-encryption type; server parameters and features are not collected</td><td>PG-SE-R</td></tr><tr><td>WAF-DATA-PG-07</td><td>Cost optimization</td><td>The tier and SKU fit the load, with scaling and start or stop for non-production</td><td>❌ Manual — servers attached with sku</td><td>PG-CO-R</td></tr><tr><td>WAF-DATA-PG-08</td><td>Operational excellence</td><td>PostgreSQL servers send diagnostics to Log Analytics</td><td>✅ diagnostic-settings coverage for the server type</td><td>PG-OE-R</td></tr><tr><td>WAF-DATA-PG-09</td><td>Operational excellence</td><td>Backups, maintenance windows and major-version currency are managed</td><td>✅ <code>customMaintenanceWindow</code>; backups are native (retention is attached as evidence) and major-version currency is not scored</td><td>PG-OE-R</td></tr><tr><td>WAF-DATA-PG-10</td><td>Performance efficiency</td><td>Query Store, Query Performance Insight, index tuning, intelligent tuning and PgBouncer are used</td><td>❌ Manual — server parameters, not collected</td><td>PG-PE-R</td></tr></tbody></table><h3 id="azure-database-for-mysql-waf-data-mys-—-9-items" tabindex="-1">Azure Database for MySQL (WAF-DATA-MYS) — 9 items <a class="header-anchor" href="#azure-database-for-mysql-waf-data-mys-—-9-items" aria-label="Permalink to &quot;Azure Database for MySQL (WAF-DATA-MYS) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-MYS-01</td><td>Reliability</td><td>MySQL servers use zone-redundant or same-zone high availability</td><td>✅ highAvailability.mode is ZoneRedundant or SameZone; failover tests are not collected</td><td>MYS-RE-R</td></tr><tr><td>WAF-DATA-MYS-02</td><td>Reliability</td><td>Tables have explicit primary keys and clients retry with backoff</td><td>❌ Manual — schema, not ARM</td><td>MYS-RE-R</td></tr><tr><td>WAF-DATA-MYS-03</td><td>Security</td><td>MySQL servers have public network access disabled</td><td>✅ network.publicNetworkAccess</td><td>MYS-SE-R</td></tr><tr><td>WAF-DATA-MYS-04</td><td>Security</td><td>TLS 1.3 is set and secure transport is required</td><td>❌ Manual — server parameters are child resources, not collected</td><td>MYS-SE-R</td></tr><tr><td>WAF-DATA-MYS-05</td><td>Security</td><td>Microsoft Entra-only authentication is used and admin credentials are held in Key Vault</td><td>❌ Manual — authentication settings are not collected</td><td>MYS-SE-R</td></tr><tr><td>WAF-DATA-MYS-06</td><td>Security</td><td>MySQL servers send diagnostic and audit logs to Log Analytics</td><td>✅ diagnostic-settings coverage for the server type</td><td>MYS-SE-R</td></tr><tr><td>WAF-DATA-MYS-07</td><td>Cost optimization</td><td>Server size, reservations, maintenance window and stop or start are chosen for cost</td><td>❌ Manual — servers attached with sku</td><td>MYS-CO-R</td></tr><tr><td>WAF-DATA-MYS-08</td><td>Operational excellence</td><td>Backups, restore tests and monitoring are in place</td><td>❌ Manual — servers attached with geo-redundant backup and retention days; restore tests and monitoring are practice, not ARM</td><td>MYS-OE</td></tr><tr><td>WAF-DATA-MYS-09</td><td>Performance efficiency</td><td>The compute tier, storage IOPS and connection handling suit the workload</td><td>❌ Manual — servers attached</td><td>MYS-PE</td></tr></tbody></table><h3 id="azure-managed-redis-waf-data-red-—-11-items" tabindex="-1">Azure Managed Redis (WAF-DATA-RED) — 11 items <a class="header-anchor" href="#azure-managed-redis-waf-data-red-—-11-items" aria-label="Permalink to &quot;Azure Managed Redis (WAF-DATA-RED) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-RED-01</td><td>Reliability</td><td>Redis high availability is on</td><td>✅ highAvailability on Redis Enterprise, and classic Basic tier (no replica) is a finding; zone count and allocation policy attached for review</td><td>AMR-RE-R</td></tr><tr><td>WAF-DATA-RED-02</td><td>Reliability</td><td>Active geo-replication, persistence and scheduled exports match the recovery need</td><td>❌ Manual — replication and persistence are not collected</td><td>AMR-RE-R</td></tr><tr><td>WAF-DATA-RED-03</td><td>Reliability</td><td>Clients use bounded retries with backoff and separate connection and command timeouts</td><td>❌ Manual — client code, not ARM</td><td>AMR-RE-R</td></tr><tr><td>WAF-DATA-RED-04</td><td>Security</td><td>Redis caches have public network access disabled</td><td>✅ publicNetworkAccess</td><td>AMR-SE-R</td></tr><tr><td>WAF-DATA-RED-05</td><td>Security</td><td>Each Redis cache has a private endpoint</td><td>✅ cache to private endpoint join</td><td>AMR-SE-R</td></tr><tr><td>WAF-DATA-RED-06</td><td>Security</td><td>Access-key authentication is disabled in favour of Microsoft Entra authentication</td><td>✅ <code>disableAccessKeyAuthentication</code> on classic caches (an explicit false is a finding; a cache that returned no flag is not scored) and <code>redisEnterpriseDatabases</code> <code>accessKeysAuthentication</code> on Redis Enterprise databases (Enabled is a finding)</td><td>AMR-SE-R</td></tr><tr><td>WAF-DATA-RED-07</td><td>Security</td><td>Non-TLS access is disabled and the minimum TLS version is 1.2</td><td>✅ enableNonSslPort and minimumTlsVersion. Certificate validation and customer-managed keys are not collected</td><td>AMR-SE-R</td></tr><tr><td>WAF-DATA-RED-08</td><td>Security</td><td>ConnectionEvents diagnostics and activity logs are collected</td><td>✅ diagnostic-settings coverage for the classic and Enterprise Redis types (a setting present, not which categories)</td><td>AMR-SE-R</td></tr><tr><td>WAF-DATA-RED-09</td><td>Cost optimization</td><td>The tier and SKU fit memory and compute needs, with reservations for steady usage and no-HA only for disposable environments</td><td>❌ Manual — caches attached with sku (now read for classic caches), capacity and high availability</td><td>AMR-CO-R</td></tr><tr><td>WAF-DATA-RED-10</td><td>Operational excellence</td><td>Instances deploy as code with health gates, dashboards, alerts and tested recovery runbooks</td><td>❌ Manual — practice, not ARM</td><td>AMR-OE-R</td></tr><tr><td>WAF-DATA-RED-11</td><td>Performance efficiency</td><td>OSS clustering, connection reuse, pipelining and co-location with the application are used</td><td>❌ Manual — caches attached with location</td><td>AMR-PE-R</td></tr></tbody></table><h3 id="azure-horizondb-waf-data-hz-—-10-items" tabindex="-1">Azure HorizonDB (WAF-DATA-HZ) — 10 items <a class="header-anchor" href="#azure-horizondb-waf-data-hz-—-10-items" aria-label="Permalink to &quot;Azure HorizonDB (WAF-DATA-HZ) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-HZ-01</td><td>Reliability</td><td>Production clusters have at least one reader node and ZoneRedundant high availability</td><td>❌ Manual — HorizonDB is not collected yet (proposed dataset in the report)</td><td>HZ-RE-R</td></tr><tr><td>WAF-DATA-HZ-02</td><td>Reliability</td><td>Applications use cluster endpoints with retry, and backup retention and geo-redundant backup match recovery needs</td><td>❌ Manual — not collected</td><td>HZ-RE-R</td></tr><tr><td>WAF-DATA-HZ-03</td><td>Reliability</td><td>Resource Health alerts exist for each cluster</td><td>❌ Manual — activity-log alert rules attached (estate-wide)</td><td>HZ-RE-R</td></tr><tr><td>WAF-DATA-HZ-04</td><td>Security</td><td>Production clusters use private endpoints, or tightly scoped firewall rules, never all-Azure-services access</td><td>❌ Manual — not collected</td><td>HZ-SE-R</td></tr><tr><td>WAF-DATA-HZ-05</td><td>Security</td><td>TLS 1.3 and secure transport are required and clients verify the server certificate</td><td>❌ Manual — not collected</td><td>HZ-SE-R</td></tr><tr><td>WAF-DATA-HZ-06</td><td>Security</td><td>Microsoft Entra-only authentication with managed identities is used, with least-privilege roles and a short extension allow-list</td><td>❌ Manual — not collected</td><td>HZ-SE-R</td></tr><tr><td>WAF-DATA-HZ-07</td><td>Security</td><td>pgaudit is on and audit logs go to Log Analytics, with Azure RBAC at least privilege on management actions</td><td>❌ Manual — not collected</td><td>HZ-SE-R</td></tr><tr><td>WAF-DATA-HZ-08</td><td>Cost optimization</td><td>Cost model, backup retention, geo-redundant backup and savings plan are chosen deliberately</td><td>❌ Manual — not collected</td><td>HZ-CO-C</td></tr><tr><td>WAF-DATA-HZ-09</td><td>Operational excellence</td><td>Clusters deploy as code with parameter groups, and monitoring covers per-node metrics</td><td>❌ Manual — not collected</td><td>HZ-OE-C</td></tr><tr><td>WAF-DATA-HZ-10</td><td>Performance efficiency</td><td>Processor type, read endpoint use, pooling and query store are set from load tests</td><td>❌ Manual — not collected</td><td>HZ-PE-R</td></tr></tbody></table><h3 id="azure-blob-storage-waf-data-blob-—-17-items" tabindex="-1">Azure Blob Storage (WAF-DATA-BLOB) — 17 items <a class="header-anchor" href="#azure-blob-storage-waf-data-blob-—-17-items" aria-label="Permalink to &quot;Azure Blob Storage (WAF-DATA-BLOB) — 17 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Pillar</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-DATA-BLOB-01</td><td>Security</td><td>Anonymous blob access is disabled on storage accounts</td><td>✅ allowBlobPublicAccess</td><td>BLOB-SE-R</td></tr><tr><td>WAF-DATA-BLOB-02</td><td>Security</td><td>Secure transfer (HTTPS) is required</td><td>✅ supportsHttpsTrafficOnly</td><td>BLOB-SE-C, BLOB-SE-S</td></tr><tr><td>WAF-DATA-BLOB-03</td><td>Security</td><td>The minimum TLS version is 1.2</td><td>✅ minimumTlsVersion; only TLS1_2 and TLS1_3 pass, so an account that never set it (which allows TLS 1.0) is a finding</td><td>BLOB-SE-R</td></tr><tr><td>WAF-DATA-BLOB-04</td><td>Security</td><td>The storage firewall denies by default</td><td>✅ networkAcls.defaultAction</td><td>BLOB-SE-C, BLOB-SE-R</td></tr><tr><td>WAF-DATA-BLOB-05</td><td>Security</td><td>Each storage account has a private endpoint for clients that run in Azure</td><td>✅ account to private endpoint join (any service)</td><td>BLOB-SE-R</td></tr><tr><td>WAF-DATA-BLOB-06</td><td>Security</td><td>Shared Key authorisation is disallowed and access uses Microsoft Entra RBAC</td><td>✅ allowSharedKeyAccess; only an explicit false passes, so an absent flag (allowed) is a finding</td><td>BLOB-SE-R, BLOB-SE-S</td></tr><tr><td>WAF-DATA-BLOB-07</td><td>Security</td><td>Customer-managed keys protect data where required</td><td>❌ Manual — customer-managed keys are requirement-driven; the accounts whose key source is not Key Vault are attached as evidence. Defender for Storage is WAF-DATA-BLOB-17</td><td>BLOB-SE-C, BLOB-SE-R</td></tr><tr><td>WAF-DATA-BLOB-08</td><td>Security</td><td>Critical data is immutable and the account is protected by a resource lock</td><td>❌ Manual — resource locks attached (estate-wide)</td><td>BLOB-SE-C, BLOB-SE-R</td></tr><tr><td>WAF-DATA-BLOB-09</td><td>Reliability</td><td>Storage accounts use zone-redundant or geo-redundant replication</td><td>✅ account sku redundancy</td><td>BLOB-RE-C</td></tr><tr><td>WAF-DATA-BLOB-10</td><td>Reliability</td><td>Soft delete, versioning and point-in-time restore are enabled</td><td>✅ <code>blobServiceProperties</code> <code>deleteRetentionEnabled</code>, <code>containerDeleteRetentionEnabled</code>, <code>versioningEnabled</code> and <code>pointInTimeRestoreEnabled</code> (any false is a finding; Data Lake and premium accounts cannot use versioning or restore, so record them as exceptions); gated on <code>blobServicePropertiesMeasured</code></td><td>BLOB-RE-R</td></tr><tr><td>WAF-DATA-BLOB-11</td><td>Reliability</td><td>Vaulted backup for blobs and a tested recovery plan exist</td><td>❌ Manual — protected items attached (estate-wide)</td><td>BLOB-RE-C, BLOB-RE-R</td></tr><tr><td>WAF-DATA-BLOB-12</td><td>Operational excellence</td><td>Storage accounts send diagnostic logs and metrics to Log Analytics</td><td>✅ diagnostic-settings coverage for the storage account type</td><td>BLOB-RE-C</td></tr><tr><td>WAF-DATA-BLOB-13</td><td>Cost optimization</td><td>Access tiers and lifecycle management move cold data to cheaper tiers</td><td>✅ <code>tieringRuleCount</code> of the storage account&#39;s lifecycle policy (one read per blob-capable account, gated on <code>lifecyclePoliciesMeasured</code>); premium block blob accounts have no tiers and are not listed</td><td>BLOB-CO</td></tr><tr><td>WAF-DATA-BLOB-14</td><td>Performance efficiency</td><td>Account type, tier and region match throughput and latency needs</td><td>❌ Manual — accounts attached with kind, sku and region</td><td>BLOB-PE</td></tr><tr><td>WAF-DATA-BLOB-15</td><td>Security</td><td>Public network access is disabled on storage accounts</td><td>✅ publicNetworkAccess; Disabled and SecuredByPerimeter pass, an absent value (enabled) is a finding. Added with the storage security projection</td><td>BLOB-SE-S</td></tr><tr><td>WAF-DATA-BLOB-16</td><td>Cost optimization</td><td>Storage accounts are general-purpose v2 or a premium kind, not a legacy general-purpose v1 or blob-only account</td><td>✅ account kind (Storage, StorageV1 and BlobStorage are findings). Added with the storage security projection; the source is the general-purpose v1 and legacy blob retirement guidance, not the Well-Architected guide</td><td>GPV1</td></tr><tr><td>WAF-DATA-BLOB-17</td><td>Security</td><td>Defender for Storage detects threats</td><td>❌ Manual — Defender plan row attached; the plan name was not re-verified. Split from WAF-DATA-BLOB-07</td><td>BLOB-SE-C, BLOB-SE-R</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>25</td><td>15</td><td>10</td></tr><tr><td>Security</td><td>46</td><td>30</td><td>16</td></tr><tr><td>Cost optimization</td><td>12</td><td>2</td><td>10</td></tr><tr><td>Operational excellence</td><td>11</td><td>4</td><td>7</td></tr><tr><td>Performance efficiency</td><td>10</td><td>0</td><td>10</td></tr><tr><td><strong>Total</strong></td><td><strong>104</strong></td><td><strong>51</strong></td><td><strong>53</strong></td></tr></tbody></table><p>Every automated item is gated on its resources, its diagnostic-coverage rows, or the <code>&lt;name&gt;Measured</code> flag of the per-resource ARM read it scores (blob service, SQL auditing and failover groups, Redis Enterprise databases), so an estate without them, or a run that never read the setting, reports the item Not assessed. The rules live in <code>src/assess/rules/waf.dataservices.yaml</code>.</p>',32)])])}const m=e(o,[["render",i]]);export{A as __pageData,m as default};
